use std::ffi::OsStr;
use std::fs;
use std::path::{Path, PathBuf};

use crate::support::run_json;

pub(super) struct BundleReports {
    pub(super) export: String,
    pub(super) import: String,
}

pub(super) fn put(cwd: &Path, lockfile: &Path) -> BundleReports {
    let bundle = cwd.join("v54_governance_handoff.project-bundle");
    let export = run_json(
        cwd,
        [
            OsStr::new("project"),
            OsStr::new("bundle"),
            OsStr::new("export"),
            lockfile.as_os_str(),
            OsStr::new("--out"),
            bundle.as_os_str(),
            OsStr::new("--format"),
            OsStr::new("json"),
        ],
    );
    let imported = tempfile::tempdir().unwrap();
    let import = run_json(
        imported.path(),
        [
            OsStr::new("project"),
            OsStr::new("bundle"),
            OsStr::new("import"),
            bundle.as_os_str(),
            OsStr::new("--format"),
            OsStr::new("json"),
        ],
    );
    let import = report_cid(&import);
    copy_object(imported.path(), cwd, &import);
    BundleReports {
        export: report_cid(&export),
        import,
    }
}

pub(super) fn export_object_roots(cwd: &Path, roots: [&str; 3]) -> PathBuf {
    let bundle = cwd.join("failed-execution-observation.bundle");
    let output = run_json(
        cwd,
        [
            OsStr::new("object"),
            OsStr::new("bundle"),
            OsStr::new("export"),
            OsStr::new(roots[0]),
            OsStr::new(roots[1]),
            OsStr::new(roots[2]),
            OsStr::new("--out"),
            bundle.as_os_str(),
            OsStr::new("--format"),
            OsStr::new("json"),
        ],
    );
    assert_eq!(output["roots"], 3);
    bundle
}

fn report_cid(output: &serde_json::Value) -> String {
    output["typed_report_cid"].as_str().unwrap().to_owned()
}

fn copy_object(from: &Path, to: &Path, cid: &str) {
    let object = |root: &Path| -> PathBuf { root.join(".unicodex/objects").join(cid) };
    fs::copy(object(from), object(to)).unwrap();
}

